<script setup>
import {ref,computed,onMounted} from 'vue'
import {api} from '../../services/api'
import {ShieldCheck,AlertCircle,RefreshCw,LockKeyhole} from 'lucide-vue-next'
const roles=ref([]),connected=ref(false),error=ref(''),selected=ref('Administrador')
const modules=['Dashboard','Banners','Prospectos','Clientes','Propiedades','Pagos','Testimonios','Usuarios','Permisos','Configuración']
const actions=['Listar','Crear','Editar','Eliminar']
async function load(){error.value='';try{const r=await api('/admin/roles');roles.value=Array.isArray(r.data)?r.data:r.data?.data||[];connected.value=true;if(roles.value.length)selected.value=roles.value[0].name}catch(e){connected.value=false;if(e.status!==404)error.value=e.message}}
const role=computed(()=>roles.value.find(r=>r.name===selected.value))
function allowed(module,action){return (role.value?.permissions||[]).some(p=>{let key=typeof p==='string'?p:p.name;return key===`${module.toLowerCase()}.${action.toLowerCase()}`})}
onMounted(load)
</script><template><section class="v28-heading"><div><span class="admin-kicker">CONTROL DE ACCESO</span><h1>Roles y permisos</h1><p>Permisos independientes para consultar, crear, editar y eliminar.</p></div><button class="admin-outline" @click="load"><RefreshCw :size="16"/> Actualizar</button></section><div v-if="error" class="admin-alert error"><AlertCircle :size="17"/>{{error}}</div><section class="v28-panel"><div class="v28-panel-head"><h2><ShieldCheck :size="19"/> Matriz de autorizaciones</h2><span class="v28-tag">{{connected?'Roles del servidor':'Vista de diseño'}}</span></div><div class="v28-role-select"><label>Perfil <select v-if="connected" v-model="selected"><option v-for="r in roles" :key="r.id" :value="r.name">{{r.name}}</option></select><select v-else v-model="selected" disabled><option>Superadministrador</option><option>Administrador</option></select></label><p>Superadministrador: control completo. Administrador: administración operativa, sin acceso a modificar permisos. Estos perfiles deben aplicarse desde Laravel, no solo ocultando botones.</p></div><div class="admin-table-wrap"><table class="admin-table v28-permission-table"><thead><tr><th>MÓDULO</th><th v-for="a in actions" :key="a">{{a.toUpperCase()}}</th></tr></thead><tbody><tr v-for="m in modules" :key="m"><td><strong>{{m}}</strong></td><td v-for="a in actions" :key="a"><input type="checkbox" :checked="connected&&allowed(m,a)" disabled :aria-label="`${m} - ${a}`"/></td></tr></tbody></table></div><div v-if="!connected" class="v28-integration"><LockKeyhole :size="18"/><span>La matriz se presenta sin permisos inventados. Para habilitarla se requiere una API de roles, autorización por acción y controles de acceso en cada endpoint de Laravel.</span></div></section></template>
